NS = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'

def col_to_num(col):
    n = 0
    for ch in col:
        n = n * 26 + (ord(ch) - ord('A') + 1)
    return n - 1

def read_sheet_grid(z, sheet_num):
    ws = ET.parse(z.open(f"xl/worksheets/sheet{sheet_num}.xml")).getroot()
    rows_dict = {}
    max_col = 0
    for row_el in ws.findall(f'.//{{{NS}}}row'):
        row_num = int(row_el.get('r', 0))
        for c in row_el.findall(f'{{{NS}}}c'):
            ref = c.get('r', '')
            col_str = ''.join(ch for ch in ref if ch.isalpha())
            col_idx = col_to_num(col_str)
            max_col = max(max_col, col_idx)
            t = c.get('t', '')
            v_el = c.find(f'{{{NS}}}v')
            is_el = c.find(f'.//{{{NS}}}t')  # inline string
            if t == 'inlineStr' and is_el is not None:
                val = is_el.text or ''
            elif v_el is not None and v_el.text is not None:
                val = v_el.text
            else:
                val = ''
            if row_num not in rows_dict:
                rows_dict[row_num] = {}
            rows_dict[row_num][col_idx] = val
    return rows_dict, max_col

