    print(f"\n{'='*60}")
    print(f"SHEET: {title}")
    print('='*60)
    for row_num in sorted(rows_dict.keys()):
        row = rows_dict[row_num]
        cells = [row.get(c, '') for c in range(max_col+1)]
        # Only print non-empty rows
        if any(c.strip() for c in cells):
            row_str = ' | '.join(f'{c:<20}' for c in cells)
            print(f"Row {row_num:3d}: {row_str}")

with zipfile.ZipFile(xlsx) as z:
    for sheet_num, sheet_name in [(1, 'Summary Cap Table'), (2, 'Convertible Ledger')]:
        rows, max_col = read_sheet_grid(z, sheet_num)
        print_grid(rows, max_col, sheet_name)
